//go:build integration

package tests

import (
	"context"
	"os"
	"os/exec"
	"path/filepath"
	"testing"
	"time"
)

// TestGRPCCoexistence compiles actual output from both RPC plugins on the same
// proto. The pinned gRPC fixture is generated by protoc-gen-go-grpc; the gRPC
// dependency stays in the scratch consumer, not the plugin module.
func TestGRPCCoexistence(t *testing.T) {
	t.Parallel()
	dir := t.TempDir()
	const module = `module coexistence.test

go 1.26.0

require (
 github.com/gopherex/natsrpc v0.1.1
 google.golang.org/grpc v1.85.0
 google.golang.org/protobuf v1.36.12
)
`
	if err := os.WriteFile(filepath.Join(dir, "go.mod"), []byte(module), 0o600); err != nil {
		t.Fatal(err)
	}
	for _, file := range []struct{ source, name string }{
		{"../example/cardinality.pb.go", "cardinality.pb.go"},
		{"../example/cardinality_natsrpc.pb.go", "cardinality_natsrpc.pb.go"},
		{"testdata/cardinality_grpc.pb.go.golden", "cardinality_grpc.pb.go"},
	} {
		source, err := os.ReadFile(file.source)
		if err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(filepath.Join(dir, file.name), source, 0o600); err != nil {
			t.Fatal(err)
		}
	}
	ctx, cancel := context.WithTimeout(t.Context(), 90*time.Second)
	defer cancel()
	cmd := exec.CommandContext(ctx, "go", "test", "-mod=mod", ".")
	cmd.Dir = dir
	cmd.Env = append(os.Environ(), "GOWORK=off")
	if output, err := cmd.CombinedOutput(); err != nil {
		t.Fatalf("compile mixed gRPC/NATS bindings: %v\n%s", err, output)
	}
}
